-    }
-
-    public IReadOnlyList<ComponentNode> Roots
-    {
-        get
-        {
-            var roots = new List<ComponentNode>();
-            foreach (var id in _rootIds)
-            {
-                if (_nodes.TryGetValue(id, out var node))
-                {
-                    roots.Add(node);
-                }
-            }
