-        {
-            node = null!;
-            return false;
-        }
-
-        var language = line[3..].Trim();
-        var codeLines = new List<string>();
-        lineIndex++;
-        while (lineIndex < lines.Length &&
-            !lines[lineIndex].StartsWith("```", StringComparison.Ordinal))
-        {
-            codeLines.Add(lines[lineIndex]);
-            lineIndex++;
-        }
-        if (lineIndex < lines.Length)
